package com.example.evcharging.finance.settlement;
import java.util.*;
public final class SettlementCalculator {private SettlementCalculator(){} public record RuleItem(String participantType,String participantId,int ratioBps){public RuleItem{if(participantType==null||participantType.isBlank())throw new IllegalArgumentException("participantType required");if(participantId==null||participantId.isBlank())throw new IllegalArgumentException("participantId required");if(ratioBps<0||ratioBps>10000)throw new IllegalArgumentException("ratioBps out of range");}} public record Allocation(String participantType,String participantId,long amountFen){}
 public static List<Allocation> calculate(long base,List<RuleItem> items){if(base<0)throw new IllegalArgumentException("negative settlement base");if(items==null||items.isEmpty())throw new IllegalArgumentException("rule items required");int total=items.stream().mapToInt(RuleItem::ratioBps).sum();if(total>10000)throw new IllegalArgumentException("total ratio exceeds 10000 bps");Set<String> keys=new HashSet<>();List<Allocation> out=new ArrayList<>();long allocated=0;int platform=-1;for(RuleItem i:items){String key=i.participantType()+":"+i.participantId();if(!keys.add(key))throw new IllegalArgumentException("duplicate participant "+key);long amount=Math.multiplyExact(base,(long)i.ratioBps())/10000L;if("PLATFORM".equalsIgnoreCase(i.participantType()))platform=out.size();out.add(new Allocation(i.participantType(),i.participantId(),amount));allocated=Math.addExact(allocated,amount);}long residual=base-allocated;if(residual>0){if(platform>=0){Allocation p=out.get(platform);out.set(platform,new Allocation(p.participantType(),p.participantId(),p.amountFen()+residual));}else out.add(new Allocation("PLATFORM","PLATFORM",residual));}if(out.stream().mapToLong(Allocation::amountFen).sum()!=base)throw new IllegalStateException("settlement not balanced");return List.copyOf(out);}}
